// A third party's contracts, for the closed rule's fixtures: under a
// `node_modules` directory, so the sweep reads them as declared outside the
// repository. Nothing here is compiled or run.

/** A listener generic in what it is handed. */
export type Listener<T> = (value: T) => void;

/** Instantiated here, outside the repository, with `unknown`. */
export declare function subscribe(listener: Listener<unknown>): void;

/** Generic: bound by its caller. */
export declare function subscribeTo<T>(listener: Listener<T>, value: T): void;

/** A receiver whose method a literal of ours implements. */
export interface Receiver {
  consume(value: any): void;
}

export declare function receive(receiver: Receiver): void;

/** A callback contract overloaded: one hands `unknown`, one `string`. */
export interface Sink {
  (value: unknown): void;
  (value: string): void;
}

export declare function drain(sink: Sink): void;

/** Listeners handed in a list, a tuple, a rest. */
export declare function listenAll(listeners: Listener<unknown>[]): void;
export declare function listenPair(listeners: [Listener<unknown>]): void;
export declare function restListeners(...listeners: Listener<unknown>[]): void;

/** A generic receiver, and one the third party instantiated with `unknown`. */
export interface Generic<T> {
  subscribe(listener: Listener<T>): void;
  consume: (value: T) => void;
}

export declare const specialised: Generic<unknown>;

/** Values the third party declares `unknown` and `any`. */
export declare const raw: unknown;
export declare const anything: any;
export declare const many: unknown[];
